Comment: The recent changes to loader being responsible for creating processes means the Thread Id isn't returned to lib.api.process. In GetProcessInitialThreadId, the call to PTEB Teb = (PTEB)NtCurrentTeb();
doesn't always hold true - testing on Win7 x64 SP1 suggests it's reliable for 32-bit, but in 1 out of every 3 or 5 executions with a 64-bit sample, the injection fails because TEB and PEB swap places when comparing loader.exe and target.exe memory layout. This behavior is untested for Win8/10.

This seems to work reliably, but might not be the right way to go about it...
```

DWORD GetProcessInitialThreadId(HANDLE ProcessHandle)
{
    DWORD ProcId;
    HANDLE hThreadSnap = INVALID_HANDLE_VALUE;
    THREADENTRY32 te32;
    DWORD ThreadId = 0;

    __try
    {
        ProcId = GetProcessId(ProcessHandle);

        // ProcId ignored for TH32CS_SNAPTHREAD...
        hThreadSnap = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, ProcId); 
        if (hThreadSnap == INVALID_HANDLE_VALUE)
            return 0;

        te32.dwSize = sizeof(THREADENTRY32);

        if (!Thread32First(hThreadSnap, &te32))
            goto out;

        do
        {
            if (te32.th32OwnerProcessID == ProcId)
            {
                ThreadId = te32.th32ThreadID;
                goto out;
            }

        } while (Thread32Next(hThreadSnap, &te32));

    out:
        CloseHandle(hThreadSnap);
        return ThreadId;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return 0;
    }
}
```
